package presentation.snippets.lesson2.slide90

import presentation.support.*

fun printOdd() {
  for (d in 1..10) {
    if (d % 2 == 0) continue
    print("$d, ")
  }
  println("done")
} // 1, 3, 5, 7, 9, done
